package org.apache.commons.lang3.math;

import java.io.*;
import java.math.*;
import java.math.BigDecimal;
import java.math.BigInteger;
import java.util.*;
import org.apache.commons.lang3.StringUtils;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class NumberUtils_createNumber_TriageGen3Test {











    @Test
    public void testCreateNumber_LongSuffix() {
        assertTrue(NumberUtils.createNumber("123L") instanceof Long);
        assertTrue(NumberUtils.createNumber("123l") instanceof Long);
        // Test BigInteger fallback for Long suffix
        String hugeLong = "9223372036854775808"; // Long.MAX_VALUE + 1
        assertTrue(NumberUtils.createNumber(hugeLong + "L") instanceof BigInteger);
    }


















}

